use verus::prelude::*;

verus! {
    /// Given a signed 8‐bit integer `n >= 1`, compute
    ///   if n % 3 == 0 then 2*(n/3) else 2*(n/3) + 1
    /// Equivalently ⌊(2*n + 1)/3⌋.  The result is always ≥ 1.
    fn solve(n: i8) -> (result: i8)
        requires n >= 1
        ensures
            // characterisation by cases on divisibility by 3
            if n % 3 == 0 {
                result == 2 * (n / 3)
            } else {
                result == 2 * (n / 3) + 1
            }
        ensures
            // the problem guarantees the result is at least 1
            result >= 1
    {
        // q = ⌊n/3⌋  (for n ≥ 1 in signed division this is the same as floor)
        let q: i8 = n / 3;

        if n % 3 == 0 {
            // exactly divisible by 3
            result = 2 * q;
        } else {
            // not divisible by 3
            result = 2 * q + 1;
        }
        // Verifier sees that this matches the above ensures clauses exactly
    }
}